#!/usr/bin/env bash
# GENERATED by rr7-starter/scripts/devcontainer-sync.mjs — do not edit here. Change devcontainer-template/sbx/ (shared) or .sbx/project.json (this project), then re-run.
# One-command Docker Sandbox for panel.
#
#   ./.sbx/run.sh                 # Claude Code, sandbox "panel", port 5195 published
#   ./.sbx/run.sh codex           # same image + kit, sandbox "panel-codex"
#   ./.sbx/run.sh shell           # plain shell, sandbox "panel-shell", no port
#   ./.sbx/run.sh claude --clone  # anything after the agent is passed to `sbx run`
#
# What it does, in order:
#   1. Makes sure the shared rr7-sbx image is loaded (built by rr7-starter/scripts/sbx-image.sh).
#   2. Makes sure a SECRETS-FREE checkout exists at $SBX_HOME/panel (default ~/sbx/panel),
#      cloning this checkout if needed. A sandbox can read every file in its workspace,
#      including an untracked .env, and a fresh clone holds committed files only.
#   3. Refuses to start if that checkout holds a .env anyway.
#   4. Runs `sbx run` there with the kit, name and port from .sbx/project.json baked in.
#      Re-running with the same agent re-attaches to the existing sandbox.
#
# Overrides: SBX_HOME (parent of the sandbox checkouts), SBX_IMAGE (default rr7-sbx:latest),
# SBX_NAME (sandbox name instead of the derived one).
set -euo pipefail

APP="panel"
PORT="5195"
AGENT="${1:-claude}"
[ $# -gt 0 ] && shift
IMAGE="${SBX_IMAGE:-rr7-sbx:latest}"
SBX_HOME="${SBX_HOME:-$HOME/sbx}"
TARGET="$SBX_HOME/$APP"

die() { echo "sbx run: $*" >&2; exit 1; }

case "$AGENT" in
  claude) NAME="${SBX_NAME:-$APP}" ;;
  codex | shell) NAME="${SBX_NAME:-$APP-$AGENT}" ;;
  *) die "unknown agent '$AGENT' (expected claude, codex or shell)" ;;
esac

command -v sbx >/dev/null || die "sbx CLI not found (see .sbx/README.md)"
command -v git >/dev/null || die "git not found"

# 1. The image. sbx keeps its own template store; `sbx template ls` prints the
#    repository as docker.io/library/<name>, so match on the bare name.
REPO="${IMAGE%%:*}"
if ! sbx template ls 2>/dev/null | awk 'NR > 1 { print $1 }' | grep -qx "docker.io/library/$REPO"; then
  die "image '$IMAGE' is not loaded into sbx. Build it once with:
    bash <your rr7-starter checkout>/scripts/sbx-image.sh"
fi

# 2. The secrets-free checkout. This script may be run from the Mac checkout
#    (~/Projects/panel) or from the sandbox checkout itself; both end up in TARGET.
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd -P)"
if [ "$HERE" != "$(cd "$TARGET" 2>/dev/null && pwd -P || true)" ]; then
  if [ ! -d "$TARGET/.git" ]; then
    echo ">>> cloning $HERE -> $TARGET (committed files only)"
    mkdir -p "$SBX_HOME"
    git clone --quiet "$HERE" "$TARGET"
    # A local clone's origin is the Mac checkout, which refuses pushes to its
    # checked-out branch. Point origin at the real remote so the agent's
    # `git push` lands where yours does. Without a remote it stays local.
    if upstream="$(git -C "$HERE" remote get-url origin 2>/dev/null)"; then
      git -C "$TARGET" remote set-url origin "$upstream"
      echo ">>> origin -> $upstream"
    fi
  fi
fi

# 3. Never hand a sandbox a rendered .env (it can read everything in the workspace).
#    Each pattern is tested on its own (`compgen -G a b` only uses its first). The
#    one .env allowed is the dev-only file the kit's start hook writes, recognised
#    by its first line, so re-attaching to a direct-mode sandbox still works.
for f in "$TARGET"/.env "$TARGET"/.env.*; do
  [ -e "$f" ] || continue
  case "${f##*/}" in .env.example) continue ;; esac
  [ "${f##*/}" = .env ] && head -n 1 "$f" | grep -q '^# Written by .sbx/kit/spec.yaml' && continue
  die "$f exists; a sandbox can read it. Remove it (or use a fresh clone)."
done

# 4. Run. `-p` matters only for agents that serve the app; it is applied at sandbox
#    creation and ignored on re-attach (use `sbx ports` to add one later).
#    macOS ships bash 3.2, where expanding an EMPTY array under `set -u` is an
#    error; the `${arr[@]+"${arr[@]}"}` form expands to nothing instead.
cd "$TARGET"
PUBLISH=()
[ "$AGENT" != "shell" ] && PUBLISH=(-p "127.0.0.1:$PORT:$PORT")
echo ">>> sbx run -t $IMAGE $AGENT --kit ./.sbx/kit --name $NAME ${PUBLISH[*]+"${PUBLISH[*]}"} $*  (in $TARGET)"
exec sbx run -t "$IMAGE" "$AGENT" --kit ./.sbx/kit --name "$NAME" ${PUBLISH[@]+"${PUBLISH[@]}"} "$@"
